#include <iostream>
#include <vector>
#include <algorithm>
int main() {
    std::vector<int> v = {3,1,4,1,5,9};
    auto it = std::find(v.begin(), v.end(), 4);
    if (it != v.end()) std::cout << "found " << *it << " at idx " << (it - v.begin()) << '\n';
    else std::cout << "not found\n";
    auto it2 = std::find(v.begin(), v.end(), 7);
    std::cout << "find 7 -> " << (it2 == v.end() ? "end" : "hit") << '\n';
    auto p = std::find_if(v.begin(), v.end(), [](int x){ return x > 5; });
    std::cout << "first >5 = " << (p != v.end() ? std::to_string(*p) : "none") << '\n';
}
